var VRM = {
	url: '{$VRM.URL}',
	user: '{$VMWARE.USERNAME}',
	pass: '{$VMWARE.PASSWORD}',
	vmware_api_session_id: {},
	result: {},

	login: function () {
		  var response, request = new HttpRequest();
			request.setHttpAuth(HTTPAUTH_BASIC, VRM.user, VRM.pass);
			request.addHeader('Accept: application/json');
			request.addHeader('Content-Type: application/json');
			response = request.post(VRM.url + '/api/rest/vr/v2/session', '');

		if (response) {
			VRM.vmware_api_session_id = JSON.parse(response).session_id;
			return true;
		}
		return false;
	 },

	logout: function () {
		var path = '/api/rest/vr/v2/session';
		var request = new HttpRequest();
		request.addHeader("x-dr-session:" + VRM.vmware_api_session_id);
		request.delete(VRM.url + path);
	},

	 getPairings: function () {
		var response, request = new HttpRequest();
		request.setHttpAuth(HTTPAUTH_NONE);
		request.addHeader("x-dr-session:" + VRM.vmware_api_session_id);
		response = request.get(VRM.url + '/api/rest/vr/v2/pairings/');

		if (response) {
			VRM.result = JSON.parse(response);
			return true;
		}
		return false;
	}
};

try {
	if (VRM.login()) {
		VRM.getPairings();
	} else {
		VRM.result = 0;
	}

	if (VRM.vmware_api_session_id) {
		VRM.logout();
	}
} catch (error) {
	VRM.result = {error: error.message};
}

return JSON.stringify( VRM.result );

var url = '{$VRM.URL}';
var user = '{$VMWARE.USERNAME}';
var pass = '{$VMWARE.PASSWORD}';
var result = {error: "Unknown error"};

try {
    var request = new HttpRequest();
    request.setHttpAuth(HTTPAUTH_BASIC, user, pass);
    request.addHeader('Accept: application/json');
    request.addHeader('Content-Type: application/json');
    var response = request.post(url + '/api/rest/vr/v2/session', '');

    if (!response) {
        result = {error: "Login failed"};
        throw new Error("Login failed");
    }

    var sessionId = JSON.parse(response).session_id;

    request = new HttpRequest();
    request.addHeader("x-dr-session: " + sessionId);
    response = request.get(url + '/api/rest/vr/v2/pairings/');

    if (!response) {
        result = {error: "Failed to get pairings"};
        throw new Error("Failed to get pairings");
    }

    var jsonData = JSON.parse(response);
    var pairingIds = [];
    if (jsonData.list && Array.isArray(jsonData.list)) {
        for (var i = 0; i < jsonData.list.length; i++) {
            var pid = jsonData.list[i].pairing_id;
            if (pid) pairingIds.push(pid);
        }
    }

    if (pairingIds.length === 0) {
        result = {error: "No pairing IDs available"};
        throw new Error("No pairing IDs");
    }

    var allReplications = [];
    for (var i = 0; i < pairingIds.length; i++) {
        request = new HttpRequest();
        request.addHeader("x-dr-session: " + sessionId);
        var apiUrl = url + '/api/rest/vr/v2/pairings/' + pairingIds[i] + '/replications?extended_info=true';
        response = request.get(apiUrl);

        if (response) {
            jsonData = JSON.parse(response);
            if (jsonData.list && Array.isArray(jsonData.list)) {
                allReplications = allReplications.concat(jsonData.list);
            }
        }
    }

    result = {list: allReplications};

} catch (error) {
    if (error.message) result = {error: error.message};
} finally {
    if (sessionId) {
        request = new HttpRequest();
        request.addHeader("x-dr-session: " + sessionId);
        request.delete(url + '/api/rest/vr/v2/session');
    }
}

return JSON.stringify(result);

