    request.addHeader("x-dr-session: " + sessionId);
    response = request.get(url + '/api/rest/vr/v2/info/');

    if (!response) {
        result = {error: "Failed to get info"};
        throw new Error("Failed to get info");
    }

	var getInfo = JSON.parse(response);


    request = new HttpRequest();
    request.addHeader("x-dr-session: " + sessionId);
    response = request.get(url + '/api/rest/vr/v2/replication-servers/');

    if (!response) {
        result = {error: "Failed to get replications server info"};
        throw new Error("Failed to get replications server info");
    } 

	var getServers = JSON.parse(response);

	getInfo.replication_servers = getServers.list;
	getInfo.error = 'none';

    result = [ getInfo ];

} catch (error) {
